question.answer:
`timescale 1ns/1ps
module tb_vote;
  reg a, b, c;
  wire y;
  integer i;
  reg expected;
  vote dut(.a(a), .b(b), .c(c), .y(y));
  initial begin
    for (i = 0; i < 8; i = i + 1) begin
      {a, b, c} = i[2:0];
      #10;
      expected = (a & b) | (a & c) | (b & c);
      if (y !== expected)
        $display("ОШИБКА: a=%b b=%b c=%b y=%b, ожидалось %b", a, b, c, y, expected);
    end
    $finish;
  end
endmodule

