question.answer:
module div6(input wire clk, input wire rst, output reg out);
  reg [1:0] cnt;
  always @(posedge clk) begin
    if (rst) begin
      cnt <= 2'd0;
      out <= 1'b0;
    end else if (cnt == 2'd2) begin
      cnt <= 2'd0;
      out <= ~out;
    end else cnt <= cnt + 2'd1;
  end
endmodule

