module divn #(parameter N = 4) (input wire clk, input wire rst, output wire strobe);
  reg [$clog2(N)-1:0] cnt;
  always @(posedge clk) begin
    if (rst) cnt <= 0;
    else if (cnt == N - 1) cnt <= 0;
    else cnt <= cnt + 1;
  end
  assign strobe = (cnt == N - 1);
endmodule

