      3'd1: data = 6'b000010;
      3'd2: data = 6'b000100;
      3'd3: data = 6'b001000;
      3'd4: data = 6'b010000;
      3'd5: data = 6'b100000;
      3'd6: data = 6'b010101;
      3'd7: data = 6'b111111;
      default: data = 6'b000000;
    endcase
  end
endmodule

