`timescale 1ns/1ps
module tb;
  reg clk;
  initial clk = 0;
  task tick; begin #5 clk = 1; #5 clk = 0; end endtask
  task rise; begin #5 clk = 1; end endtask
  task fall; begin #5 clk = 0; end endtask
  reg rst, start;
  reg [7:0] data;
  wire tx, busy;
  integer i, k;
  reg [7:0] got;
  reg stopbit;
  uart_tx #(.CLKS(4)) dut(.clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy));
  task show; begin #1; $display("byte=%h stop=%b tx=%b busy=%b", got, stopbit, tx, busy); end endtask
  task xfer(input [7:0] b);
    begin
      data = b; start = 1; tick; start = 0;
      i = 0;
      while (tx !== 1'b0 && i < 40) begin tick; i = i + 1; end
      repeat (2) tick;
      for (k = 0; k < 8; k = k + 1) begin repeat (4) tick; got[k] = tx; end
      repeat (4) tick; stopbit = tx;
      repeat (4) tick;
    end
  endtask

  initial begin
    {{ TEST.testcode }}
    $finish;
  end
endmodule

question.answer:
module uart_tx #(parameter CLKS = 4) (input wire clk, input wire rst, input wire start,
                                    input wire [7:0] data, output reg tx, output wire busy);
  localparam IDLE = 2'd0, START = 2'd1, DATA = 2'd2, STOP = 2'd3;
  reg [1:0] state;
  reg [$clog2(CLKS)-1:0] clks;
  reg [2:0] idx;
  reg [7:0] shreg;
  assign busy = (state != IDLE);
  always @(posedge clk) begin
    if (rst) begin
      state <= IDLE; tx <= 1'b1; clks <= 0; idx <= 3'd0;
    end else case (state)
      IDLE: if (start) begin shreg <= data; tx <= 1'b0; clks <= 0; state <= START; end
            else tx <= 1'b1;
      START: if (clks == CLKS - 1) begin clks <= 0; idx <= 3'd0; tx <= shreg[0]; state <= DATA; end
             else clks <= clks + 1;
      DATA: if (clks == CLKS - 1) begin
              clks <= 0;
              if (idx == 3'd7) begin tx <= 1'b1; state <= STOP; end
              else begin idx <= idx + 3'd1; tx <= shreg[idx + 3'd1]; end
            end else clks <= clks + 1;
      STOP: if (clks == CLKS - 1) begin clks <= 0; state <= IDLE; end
            else clks <= clks + 1;
    endcase
  end
endmodule
